input.cv_html:
{#- classic: the command line's layout re-expressed. A header with the photo, the name, the
    headline and the contact lines between two rules, then one row per section: its label in a
    narrow column on the left, its body on the right. An empty section is not printed. -#}
{% extends "_base/page.html.j2" %}
{% import "_base/macros.html.j2" as base with context %}
{% block body %}
<div class="bar"></div>
{{ base.header(content.headline) }}
<div class="bar"></div>

{% if content.summary or content.highlights or content.competencies %}
<section class="row">
<h2 class="label">{{ base.label("summary") }}</h2>
<div class="body">
{% if content.summary %}<p class="summary">{{ content.summary }}</p>{% endif %}
{% if content.highlights or content.competencies %}
<div class="about-cols">
{% if content.highlights %}
<div>
<h3 class="sub">{{ base.label("highlights") }}</h3>
{{ base.bullets(content.highlights) }}
</div>
{% endif %}
{% if content.competencies %}
<div>
<h3 class="sub">{{ base.label("competencies") }}</h3>
{{ base.bullets(content.competencies, "competencies") }}
</div>
{% endif %}
</div>
{% endif %}
</div>
</section>
{% endif %}

{% if roles %}
<section class="row">
<h2 class="label">{{ base.label("experience") }}</h2>
<div class="body">
{% for role in roles %}
{{ base.employer(role) }}
{% endfor %}
</div>
</section>
{% endif %}

{% if schools %}
<section class="row">
<h2 class="label">{{ base.label("education") }}</h2>
<div class="body schools">
{% for item in schools %}
{{ base.school(item) }}
{% endfor %}
</div>
</section>
{% endif %}

{% if content.skills %}
<section class="row">
<h2 class="label">{{ base.label("skills") }}</h2>
<div class="body skills">
{% for group in content.skills %}
{{ base.skill_group(group) }}
{% endfor %}
</div>
</section>
{% endif %}

{% if languages %}
<section class="row">
<h2 class="label">{{ base.label("languages") }}</h2>
<div class="body">
<ul class="languages">
{% for item in languages %}
{{ base.language(item) }}
{% endfor %}
</ul>
</div>
</section>
{% endif %}
{% endblock %}

input.letter_html:
{#- classic, the letter: the CV's header, then the date, the recipient, the subject, the
    salutation, the paragraphs, the closing and the name. -#}
{% extends "_base/page.html.j2" %}
{% import "_base/macros.html.j2" as base with context %}
{% block body %}
<div class="bar"></div>
{{ base.header(content.headline) }}
<div class="bar"></div>

<div class="letter-body">
{{ base.letter_date() }}
{% if content.recipient %}<p class="recipient">{{ content.recipient }}</p>{% endif %}
{% if content.subject %}<p class="subject"><strong>{{ base.label("subject") }}</strong> {{ content.subject }}</p>{% endif %}
{% if content.salutation %}<p class="salutation">{{ content.salutation }}</p>{% endif %}
{{ base.paragraphs(content.paragraphs) }}
{% if content.closing %}<p class="closing">{{ content.closing }}</p>{% endif %}
<p class="signature">{{ name }}</p>
</div>
{% endblock %}

input.css:
/* classic: one column, sans (Nunito Sans, the bundled stand in for the command line's Avenir),
   a label column on the left of each section, rules between the sections. The density comes
   from the step on :root: --body-size, --line-height, --section-gap, --item-gap, --margin. */
@page { size: A4; }
* { box-sizing: border-box; }
html {
  font-family: "Arimo", sans-serif;
  font-size: var(--body-size);
  line-height: var(--line-height);
  color: #1d232b;
}
body { margin: 0; }
p, ul, h1, h2, h3 { margin: 0; padding: 0; }
a { color: inherit; text-decoration: none; }
li, p { overflow-wrap: anywhere; }

.bar { border-top: 2.5px solid #1d232b; }

.head {
  display: flex;
  gap: 14pt;
  align-items: center;
  padding: 9pt 0;
}
.photo {
  width: 25mm;
  height: 25mm;
  object-fit: cover;
  border-radius: 50%;
  flex: 0 0 auto;
}
.headtext { flex: 1 1 auto; }
.name {
  font-size: 2.35em;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.01em;
}
.headline {
  font-size: 1.15em;
  color: var(--accent);
  font-weight: 600;
  margin-top: 2pt;
}
.contact {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 1pt 12pt;
  margin-top: 5pt;
  color: #4a525e;
}

.row {
  display: flex;
  gap: 10pt;
  padding: var(--section-gap) 0;
  border-bottom: 0.75px solid #c9d0d9;
}
.row:last-child { border-bottom: 0; }
.label {
  flex: 0 0 27mm;
  font-size: 0.82em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--accent);
  padding-top: 0.2em;
}
.body { flex: 1 1 auto; }

.summary { margin-bottom: var(--item-gap); }
.about-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12pt;
}
.sub, .group-label {
  font-size: 0.86em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #4a525e;
  margin-bottom: 1pt;
}
.body ul { padding-left: 1.05em; }
.body li { margin-bottom: 1pt; }
.body li::marker { color: var(--accent); }

.entry { margin-bottom: var(--item-gap); }
.entry:last-child { margin-bottom: 0; }
.entry-head {
  display: flex;
  justify-content: space-between;
  gap: 10pt;
  align-items: baseline;
}
.entry-title { font-size: 1.04em; font-weight: 700; }
.org { font-weight: 600; }
.entry .org { color: var(--accent); }
.period, .place { color: #5a6270; font-size: 0.92em; }
.entry-head .period { flex: 0 0 auto; text-align: right; }

.schools {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--item-gap) 12pt;
}
.skills {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--item-gap) 12pt;
}
.languages {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 2pt 16pt;
}
.body .languages { padding-left: 0; }

.letter-body { padding-top: 14pt; }
.letter-body p { margin-bottom: var(--item-gap); }
.date { text-align: right; color: #4a525e; }
.recipient { margin-top: var(--section-gap); }
.subject { margin: var(--section-gap) 0; }
.paragraph { text-align: justify; white-space: pre-line; }
.closing { margin-top: var(--section-gap); }
.signature { font-weight: 700; margin-top: var(--section-gap); }

@import "x.css";

